INSERT INTO questions_entretien (id,candidat_id,questions_json,posees_json,coche_par_json,updated_at) VALUES (2,2,'["En tant qu''architecte de solutions, quels patterns architecturaux (microservices, SOA, event-driven) avez-vous déployés concrètement, et dans quel contexte avez-vous choisi l''un plutôt qu''un autre ?", "Comment garantissez-vous la sécurité, la scalabilité et l''interopérabilité d''un système d''information dans un environnement multi-entités comme une agence publique régionale ?", "Votre formation est en informatique, non en architecture du bâtiment — comment compensez-vous cette différence par rapport au titre du poste, et quelle valeur ajoutée apportez-vous concrètement à un projet de type « Chef de Projets Architecte » ?", "Sur vos 8 années d''expérience, citez un projet complexe que vous avez piloté de A à Z : quelles étaient les contraintes, les risques rencontrés et comment les avez-vous gérés ?", "Avez-vous déjà travaillé avec des équipes pluridisciplinaires ou des prestataires externes ? Comment organisez-vous la coordination et le suivi des livrables ?", "Votre score de correspondance au poste est de 67,4% — selon vous, quels sont les écarts entre votre profil actuel et les exigences du poste, et comment comptez-vous les combler ?", "Pourquoi postulez-vous à un poste de chef de projets dans le secteur public alors que le secteur privé offre généralement des rémunérations plus compétitives pour votre profil ?", "Dans cinq ans, où vous voyez-vous professionnellement, et en quoi ce poste à l''ADER s''inscrit-il dans cette trajectoire ?", "Que savez-vous du rôle et des missions de l''Agence de Développement Régional de Fès-Meknès, et quels sont selon vous les défis numériques ou infrastructurels prioritaires pour la région ?", "La gestion de projets en milieu public implique des contraintes spécifiques : marchés publics, délais administratifs, reddition de comptes — avez-vous déjà été confronté à ce cadre, et comment vous y adaptez-vous ?"]','[]','{}','2026-08-27 13:25:45.016067') ON CONFLICT (id) DO NOTHING;